'use strict';

// MODULES //

var isArray = require( '@stdlib/assert/is-array' );
var isPlainObject = require( '@stdlib/assert/is-plain-object' );
var format = require( '@stdlib/string/format' );
var shallowClone = require( './shallow_clone.js' );
var isSafeToken = require( './is_safe_token.js' );
var resolveToken = require( './resolve_token.js' );


// MAIN //

/**
* Immutably deletes a value at a path in a document using structural sharing.
*
* ## Notes
*
* -   Only objects/arrays along the path are shallow-cloned. All other subtrees keep their original references.
*
* @private
* @param {(Object|Array)} document - the source document
* @param {Array<string>} tokens - array of reference tokens
* @throws {Error} tokens must not be empty
* @throws {Error} tokens must not contain unsafe tokens
* @throws {TypeError} intermediate path segments must reference objects or arrays
* @returns {(Object|Array)} new document with the value at the specified path removed
*
* @example
* var doc = { 'a': { 'b': 1, 'c': 2 } };
* var out = deleteIn( doc, [ 'a', 'b' ] );
* // returns { 'a': { 'c': 2 } }
*
* var bool = ( 'b' in out.a );
* // returns false
*
* @example
* var doc = { 'a': [ 1, 2, 3 ] };
* var out = deleteIn( doc, [ 'a', '1' ] );
* // returns { 'a': [ 1, 3 ] }
*/
function deleteIn( document, tokens ) {
	var current;
	var child;
	var root;
	var key;
	var i;

	if ( tokens.length === 0 ) {
		throw new Error( 'invalid argument. Cannot delete the root of a document.' );
	}

	root = shallowClone( document );
	current = root;

	// Walk all tokens except the last, cloning each level:
	for ( i = 0; i < tokens.length - 1; i++ ) {
		if ( !isSafeToken( tokens[ i ] ) ) {
			throw new Error( format( 'invalid argument. Token contains an unsafe value. Value: `%s`.', tokens[ i ] ) );
		}
		key = resolveToken( current, tokens[ i ] );

		if ( !isPlainObject( current[ key ] ) && !isArray( current[ key ] ) ) {
			throw new TypeError( format( 'invalid argument. Path references a non-traversable value at token `%s`.', tokens[ i ] ) );
		}
		child = shallowClone( current[ key ] );
		current[ key ] = child;
		current = child;
	}

	// Delete the value at the final token:
	if ( !isSafeToken( tokens[ tokens.length - 1 ] ) ) {
		throw new Error( format( 'invalid argument. Token contains an unsafe value. Value: `%s`.', tokens[ tokens.length - 1 ] ) );
	}
	key = resolveToken( current, tokens[ tokens.length - 1 ] );

	if ( isArray( current ) ) {
		current.splice( key, 1 );
	} else {
		delete current[ key ];
	}

	return root;
}


// EXPORTS //

module.exports = deleteIn;
